INSERT INTO tenant_configs (tenant_id, branding, home, about, contact, social, footer, settings) VALUES
  ('90e0cffb-7650-588f-84e9-a79ca322ad46'::uuid, '{"logoUrl":"/tenants/royal/logo.svg","faviconUrl":"/tenants/royal/favicon.svg","primaryColor":"#A0763A","secondaryColor":"#5A1F2B","heroImageUrl":"https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=2000&q=70","tag… weddings, timelessly told"}'::jsonb, '{"headline":"Timeless weddings, told with royal grace.","subheadline":"Jaipur''s award-winning wedding photographers — candid, cinematic and rooted in tradition.","heroCtaLabel":"Book your date","featuredPhotoUrls":["https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1200&q=70","htt…::jsonb, '{"title":"Three generations of royal storytelling","intro":"Royal Wedding Photography was founded in a Jaipur courtyard in 2012 with one borrowed camera and a belief: every wedding is a family heirloom in the making.","history":"What began as a two-person team shooting haveli weddings now has four full-time photographers, a film unit and an editing studio. We have documented more than 850 celebrations across Rajasthan, Udaipur palaces and destination venues in Goa and Kerala.","philosophy":"We photograph feelings first and poses second. Our team blends in, anticipates the quiet moments — a mother adjusting a veil, a grandfather’s blessing — and edits with a warm, film-inspired palette that ages gracefully.","achievements":[{"label":"Weddings covered","value":"850+"},{"label":"Years of experience","value":"14"},{"label":"Destination shoots","value":"120+"},{"label":"Average rating","value":"4.9★"}],"milestones":[{"year":"2012","text":"Studio founded in Jaipur"},{"year":"2016","text":"Launched cinematic film division"},{"year":"2020","text":"Introduced next-day highlight delivery"},{"year":"2024","text":"Featured in WeddingSutra Top 50"}]}'::jsonb, '{"email":"hello@royalweddingphotography.in","phone":"+91 98290 11122","whatsapp":"919829011122","address":"14, Bani Park Road, Jaipur, Rajasthan 302016","city":"Jaipur","mapUrl":"https://maps.google.com/?q=Bani+Park+Jaipur","hours":"Mon–Sat · 10:00–19:00"}'::jsonb, '{"instagram":"https://instagram.com/royalweddingphotography","facebook":"https://facebook.com/royalweddingphotogr…::jsonb, '{"text":"Heritage weddings, timelessly told. Based in Jaipur, travelling worldwide.","copyright":"© 2026 Royal Wedding Photography. All rights reserved."}'::jsonb, '{"currency":"INR","locale":"en-IN","deliveryTargetHours":24,"booking":{"enquiryEnabled":true,"autoConfirm":false,"requireDeposit":true,"depositPercent":30,"minLeadDays":7},"notifications":{"emailOnNewBooking":true,"emailOnDelivery":true,"smsReminders":false,"reminderDaysBefore":3},"business":{"legalName":"Royal Wedding Photography Pvt. Ltd.","taxId":"08ABCDE1234F1Z5","invoicePrefix":"RWP","timezone":"Asia/Kolkata"}}'::jsonb),
  ('c35cfbf3-52a4-59e7-be00-644047808ce6'::uuid, '{"logoUrl":"/tenants/dream/logo.svg","faviconUrl":"/tenants/dream/favicon.svg","primaryColor":"#C0675A","secondaryColor":"#2F4858","heroImageUrl":"https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=2000&q=70","tag… stories, dreamlike light"}'::jsonb, '{"headline":"Moments that feel like a dream.","subheadline":"Mumbai-based candid photographers capturing love stories, milestones and the little things in between.","heroCtaLabel":"Plan your shoot","featuredPhotoUrls":["https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=1200&q=70","htt…::jsonb, '{"title":"Candid at heart, cinematic by craft","intro":"Dream Moments Studio is a small, close-knit team of Mumbai photographers who believe the best photographs happen when nobody is posing.","history":"Started by Kabir Anand in 2017 after a decade in photojournalism, the studio has grown into a boutique practice focused on weddings, pre-wedding stories and family milestones.","philosophy":"Soft light, honest emotion, zero stiffness. We guide gently and let real moments unfold.","achievements":[{"label":"Stories told","value":"520+"},{"label":"Years","value":"9"},{"label":"Cities","value":"14"},{"label":"Rating","value":"4.8★"}],"milestones":[{"year":"2017","text":"Dream Moments founded"},{"year":"2021","text":"Opened Bandra studio"},{"year":"2025","text":"Launched client portal with next-day highlights"}]}'::jsonb, '{"email":"hello@dreammoments.studio","phone":"+91 98200 55501","whatsapp":"919820055501","address":"7, Carter Road, Bandra West, Mumbai 400050","city":"Mumbai","mapUrl":"https://maps.google.com/?q=Carter+Road+Bandra","hours":"Tue–Sun · 11:00–20:00"}'::jsonb, '{"instagram":"https://instagram.com/dreammomentsstudio","facebook":"https://facebook.com/dreammomentsstudio","you…::jsonb, '{"text":"Candid stories, dreamlike light — Mumbai & beyond.","copyright":"© 2026 Dream Moments Studio."}'::jsonb, '{"currency":"INR","locale":"en-IN","deliveryTargetHours":24,"booking":{"enquiryEnabled":true,"autoConfirm":false,"requireDeposit":true,"depositPercent":30,"minLeadDays":7},"notifications":{"emailOnNewBooking":true,"emailOnDelivery":true,"smsReminders":false,"reminderDaysBefore":3},"business":{"legalName":"Dream Moments Studio LLP","taxId":"27AAAFD1234Q1ZP","invoicePrefix":"DMS","timezone":"Asia/Kolkata"}}'::jsonb),
  ('c2bc14c2-62b8-52f0-90d1-4364d3c1fb90'::uuid, '{"logoUrl":"/tenants/pixel/logo.svg","faviconUrl":"/tenants/pixel/favicon.svg","primaryColor":"#2F6F73","secondaryColor":"#1F2A44","heroImageUrl":"https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=2000&q=70","tag… images for ambitious brands"}'::jsonb, '{"headline":"Sharp images for ambitious brands.","subheadline":"Product, corporate and fashion photography from a Pune studio built for speed, consistency and clean lighting.","heroCtaLabel":"Request a quote","featuredPhotoUrls":["https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=1200&q=70","htt…::jsonb, '{"title":"A studio built for brands","intro":"Pixel Photography helps e-commerce brands, startups and corporates look consistent and credible — on every channel.","history":"Founded in 2024 by Nikhil Joshi, Pixel runs a 1,200 sq ft daylight and strobe studio in Koregaon Park.","philosophy":"Clarity, consistency and fast turnaround.","achievements":[{"label":"Brands served","value":"60+"},{"label":"Products shot","value":"9,000+"},{"label":"Turnaround","value":"48h"}],"milestones":[{"year":"2024","text":"Studio opened in Pune"},{"year":"2026","text":"Joined shivamStudio platform"}]}'::jsonb, '{"email":"studio@pixelphotography.in","phone":"+91 98220 33344","whatsapp":"919822033344","address":"21, Lane 6, Koregaon Park, Pune 411001","city":"Pune","mapUrl":"https://maps.google.com/?q=Koregaon+Park+Pune","hours":"Mon–Fri · 09:30–18:30"}'::jsonb, '{"instagram":"https://instagram.com/pixelphotography.in","youtube":"https://youtube.com/@pixelphotography"}'::jsonb, '{"text":"Product, corporate & fashion photography — Pune.","copyright":"© 2026 Pixel Photography."}'::jsonb, '{"currency":"INR","locale":"en-IN","deliveryTargetHours":48,"booking":{"enquiryEnabled":true,"autoConfirm":false,"requireDeposit":true,"depositPercent":30,"minLeadDays":7},"notifications":{"emailOnNewBooking":true,"emailOnDelivery":true,"smsReminders":false,"reminderDaysBefore":3},"business":{"legalName":"Pixel Photography","taxId":"27AAAPJ1234K1Z2","invoicePrefix":"PXP","timezone":"Asia/Kolkata"}}'::jsonb),
  ('569af8e7-afd8-565f-a7fc-e7162ceafcfb'::uuid, '{"logoUrl":"/tenants/creative/logo.svg","faviconUrl":"/tenants/creative/favicon.svg","primaryColor":"#6B5B95","secondaryColor":"#2B2D42","heroImageUrl":"https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=2000&q=70","tag… with personality"}'::jsonb, '{"headline":"Portraits with personality.","subheadline":"Editorial portraits, fashion and couples photography in Austin, Texas.","heroCtaLabel":"Book a session","featuredPhotoUrls":["https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=1200&q=70","htt…::jsonb, '{"title":"Light, texture and a little rebellion","intro":"Creative Lens Studio is an Austin collective of editorial photographers.","history":"Founded in 2020 by Jordan Lee, the studio blends fashion-world polish with the warmth of portrait work.","philosophy":"Every face has a story; our job is to light it honestly.","achievements":[{"label":"Sessions","value":"1,100+"},{"label":"Years","value":"6"}],"milestones":[{"year":"2020","text":"Studio founded"}]}'::jsonb, '{"email":"hello@creativelens.studio","phone":"+1 512 555 0142","whatsapp":"15125550142","address":"1200 S Congress Ave, Austin, TX 78704","city":"Austin","mapUrl":"https://maps.google.com/?q=S+Congress+Ave+Austin","hours":"Wed–Sun · 10:00–18:00"}'::jsonb, '{"instagram":"https://instagram.com/creativelensstudio"}'::jsonb, '{"text":"Editorial portraits & fashion — Austin, TX.","copyright":"© 2026 Creative Lens Studio."}'::jsonb, '{"currency":"USD","locale":"en-US","deliveryTargetHours":72,"booking":{"enquiryEnabled":true,"autoConfirm":false,"requireDeposit":true,"depositPercent":30,"minLeadDays":7},"notifications":{"emailOnNewBooking":true,"emailOnDelivery":true,"smsReminders":false,"reminderDaysBefore":3},"business":{"legalName":"Creative Lens Studio LLC","taxId":"88-1234567","invoicePrefix":"CLS","timezone":"America/Chicago"}}'::jsonb)
