INSERT INTO photographers (id, tenant_id, user_id, name, slug, title, bio, avatar_url, email, phone, experience_years, rating, specialties, skills, equipment, portfolio, status, featured, availability, created_at) VALUES
  ('8b64ddce-8f6f-515c-be54-af0d690e1c95'::uuid, '90e0cffb-7650-588f-84e9-a79ca322ad46'::uuid, '3b942860-121a-5fe2-b511-4e43059ae57d'::uuid, 'Aarav Mehta', 'aarav-mehta', 'Lead Wedding Photographer', 'Twelve years of photographing palace weddings across Rajasthan. Aarav leads our candid storytelling team and edits every hero frame himself.', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=300&q=70', 'aarav@royal.demo', '+91 98290 22201', 12, 4.9, ARRAY['wedding','pre-wedding','engagement']::text[], ARRAY['Candid storytelling','Cinematic lighting','Drone','Lightroom grading']::text[], ARRAY['Sony A1','35mm f/1.4 GM','85mm f/1.2 GM']::text[], ARRAY['https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=900&q=70','http…text[], 'active', true, jsonb_build_object('weekdays', '[1,2,3,4,5,6,0]'::jsonb, 'blockedDates', (SELECT coalesce(jsonb_agg(pg_temp.sd(d::date)), '[]'::jsonb) FROM unnest(ARRAY['2026-11-27','2026-11-28']) AS d), 'note', 'Booked for the Kapoor wedding on 27 Nov.'), pg_temp.st('2026-01-10T10:00:00.000Z')),
