  ('8f0ba285-c7b6-5acb-8974-70df423aed86'::uuid, '90e0cffb-7650-588f-84e9-a79ca322ad46'::uuid, 'Aditi Sharma', 'Bride · Rambagh Palace', 'wedding', 5, 'They disappeared into the background and still caught every tear and laugh. The highlights arrived the next morning and my mother cried all over again.', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=300&q=70', true, pg_temp.st('2026-09-09T10:00:00.000Z')),
  ('a20b3aff-2091-565c-815a-65ddc68249e4'::uuid, '90e0cffb-7650-588f-84e9-a79ca322ad46'::uuid, 'Meera Kapoor', 'Bride · Udaipur', 'engagement', 5, 'Simran made us feel completely at ease. We booked the wedding the very same week.', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=300&q=70', true, pg_temp.st('2026-09-17T10:00:00.000Z')),
  ('8b56fd5c-63bd-531c-84e7-d0dac80332a7'::uuid, '90e0cffb-7650-588f-84e9-a79ca322ad46'::uuid, 'Karan Malhotra', 'Director, Malhotra Textiles', 'corporate', 5, 'Professional, punctual and the images were on our dealer app within a day.', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=300&q=70', true, pg_temp.st('2026-11-03T10:00:00.000Z')),
  ('63633fa5-e9e3-5aa3-93c4-70d1172c7754'::uuid, '90e0cffb-7650-588f-84e9-a79ca322ad46'::uuid, 'Neha Gupta', 'Host · Diwali Party', 'event', 4, 'Great energy and lovely candids of the whole family.', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=300&q=70', false, pg_temp.st('2026-07-09T10:00:00.000Z')),
  ('fb7e87eb-ffee-5dbd-b383-95c79de99aae'::uuid, 'c35cfbf3-52a4-59e7-be00-644047808ce6'::uuid, 'Sameer Khanna', 'Father · Powai', 'birthday', 5, 'Ananya had forty kids smiling at the camera — a miracle!', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=300&q=70', true, pg_temp.st('2026-10-31T10:00:00.000Z')),
  ('05a5a675-982e-502b-b3ca-07baaa5684ca'::uuid, 'c35cfbf3-52a4-59e7-be00-644047808ce6'::uuid, 'Riya Shah', 'Bride-to-be · Mumbai', 'pre-wedding', 5, 'The Marine Drive shoot felt like a movie. The client portal made delivery so easy.', 'https://images.unsplash.com/photo-1531746020798-e6953c6e8e04?auto=format&fit=crop&w=300&q=70', true, pg_temp.st('2026-11-04T10:00:00.000Z')),
  ('deec8506-e8c0-5362-8fb5-1cf99acc6fa3'::uuid, 'c35cfbf3-52a4-59e7-be00-644047808ce6'::uuid, 'Neelam Rao', 'Bride · Juhu', 'wedding', 5, 'Candid, warm and exactly what we wanted.', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=300&q=70', true, pg_temp.st('2026-06-19T10:00:00.000Z')),
  ('ea108d79-1475-5276-8622-b71d73dedb3c'::uuid, 'c2bc14c2-62b8-52f0-90d1-4364d3c1fb90'::uuid, 'Aura Cosmetics', 'E-commerce brand', 'product', 5, 'Clean, consistent and marketplace-ready every single time.', 'https://images.unsplash.com/photo-1489424731084-a5d8b219a5bb?auto=format&fit=crop&w=300&q=70', true, pg_temp.st('2026-10-28T10:00:00.000Z')),
  ('91f8f0fa-958e-549c-bf10-bfeb86b7cc40'::uuid, 'c2bc14c2-62b8-52f0-90d1-4364d3c1fb90'::uuid, 'Rohit Deshmukh', 'Founder, Brewline', 'portrait', 5, 'Our founder portraits finally look like us.', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=300&q=70', true, pg_temp.st('2026-10-07T10:00:00.000Z')),
  ('2f5ec1d3-9171-51a5-a24a-254e76443315'::uuid, '569af8e7-afd8-565f-a7fc-e7162ceafcfb'::uuid, 'Chloe Bennett', 'Model & creative', 'fashion', 5, 'Jordan’s direction is incredible. The best portfolio I have ever had.', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=300&q=70', true, pg_temp.st('2026-10-22T10:00:00.000Z')),
  ('560120fc-e027-5a81-92e3-ae9c2cea4957'::uuid, '569af8e7-afd8-565f-a7fc-e7162ceafcfb'::uuid, 'Anthony Cruz', 'Musician', 'portrait', 5, 'Moody, honest, unforgettable portraits.', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=300&q=70', true, pg_temp.st('2026-09-07T10:00:00.000Z'))
INSERT INTO blog_posts (id, tenant_id, slug, title, excerpt, body, cover_url, category, author_name, read_minutes, published_at, status) VALUES
  ('759a11c4-f799-53ba-a24f-ebf743309a72'::uuid, '90e0cffb-7650-588f-84e9-a79ca322ad46'::uuid, 'wedding-photography-timeline', 'How to Plan Your Wedding-Day Photography Timeline', 'A practical hour-by-hour guide so nothing important is missed — and you still enjoy your own wedding.', 'Start from the ceremony time and work backwards. Allow 90 minutes for bridal portraits and getting ready, 45 minutes for family formals and at least 30 minutes of golden-hour portraits with your partner.
